{
  "segment_function": "To analyze the permanence of works of art as objects without utility that provide the human artifice with ultimate durability and represent worldly stability and a premonition of mortality's achievement.",
  "claims": [
    {
      "claim": "Works of art possess supreme durability and distinct uselessness, standing apart from ordinary use objects and exchange markets.",
      "claim_type": "author_position",
      "supporting_excerpt": "Among the things that give the human artifice the stability without which it could never be a reliable home for men are a number of objects which are strictly without any utility whatsoever and which, moreover, because they are unique, are not exchangeable and therefore defy equalization through a common denominator such as money",
      "support_kind": "direct",
      "qualifications": [
        "applies specifically to works of art within the human artifice"
      ],
      "confidence": 1
    },
    {
      "claim": "The immediate source of the art work is the human capacity for thought.",
      "claim_type": "author_position",
      "supporting_excerpt": "The immediate source of the art work is the human capacity for thought, as man’s “propensity to truck and barter” is the source of exchange objects, and as his ability to use is the source of use things.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "works of art",
      "definition": "Objects that give the human artifice stability, are strictly without utility, are unique and non-exchangeable, and possess an outstanding permanence untouched by the corroding effect of natural processes."
    }
  ],
  "distinctions": [
    {
      "item_a": "proper intercourse with a work of art",
      "item_b": "using an ordinary use object",
      "distinction": "Proper intercourse with art requires removing it carefully from the whole context of ordinary use objects and daily wants, whereas ordinary use objects are subject to use that can destroy art."
    }
  ],
  "unresolved_context": [
    "Plato's view on Protagoras and a god as the measure of all things."
  ],
  "must_not_be_lost": [
    "Art objects achieve their permanence through uselessness and freedom from daily use.",
    "Thought is the human capacity from which art works spring, transforming internal feelings into reified worldly things."
  ]
}

